using System.Net;
using System.Text.Json;
using System.Text.Json.Nodes;
using IrodoriTts.Audio;

namespace IrodoriTts.Server.Tests;

/// <summary>Long input split into pieces (Irodori-TTS-Server's chunking) and stream_format "sse".</summary>
public class ChunkingTests
{
    // 4 pieces at chunk_min_chars 10 (see Data/chunk_ref.json).
    private const string LongText = "今日は良い天気ですね。散歩に出かけたら、公園で桜がきれいに咲いていました。少し風が冷たかったけれど、とても気持ちの良い一日でした。";

    public sealed record Case(string Text, int Min, int? First, string[] Expected);

    /// <summary>Generated by running Irodori-TTS-Server's own <c>_split_text_for_speech</c>.</summary>
    public static IEnumerable<TheoryDataRow<Case>> PythonCases()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "Data", "chunk_ref.json")));
        foreach (var c in doc.RootElement.EnumerateArray())
        {
            yield return new TheoryDataRow<Case>(new Case(
                c.GetProperty("text").GetString()!,
                c.GetProperty("min").GetInt32(),
                c.GetProperty("first").ValueKind == JsonValueKind.Null ? null : c.GetProperty("first").GetInt32(),
                c.GetProperty("expected").EnumerateArray().Select(x => x.GetString()!).ToArray()));
        }
    }

    [Theory]
    [MemberData(nameof(PythonCases))]
    public void SplitMatchesIrodoriTtsServer(Case c)
    {
        Assert.Equal(c.Expected, SpeechChunker.Split(c.Text, c.Min, c.First));
    }

    [Fact]
    public void TailWithoutLettersStaysWithThePreviousPiece()
    {
        Assert.Equal(["「こんにちは。」"], SpeechChunker.Split("「こんにちは。」", 3));
    }

    private static void Voices(string dir) => TestServer.WriteWav(Path.Combine(dir, "alice.wav"));

    private static JsonObject Speech(string text, JsonObject? irodori = null) => new()
    {
        ["model"] = "irodori-tts",
        ["input"] = text,
        ["voice"] = "alice",
        ["irodori"] = irodori ?? new JsonObject { ["chunk_min_chars"] = 10 },
    };

    [Fact]
    public async Task LongInputIsSynthesizedPieceByPieceWithOneSeedAndStreamed()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        s.Engine.StreamPieces = 2;

        var r = await s.SpeechAsync(Speech(LongText));

        Assert.Equal(HttpStatusCode.OK, r.StatusCode);
        var texts = s.Engine.Requests.Select(x => x.Text).ToArray();
        Assert.Equal(SpeechChunker.Split(LongText, 10), texts);
        var seed = s.Engine.Requests[0].Seed;
        Assert.NotNull(seed);
        Assert.All(s.Engine.Requests, x => Assert.Equal(seed, x.Seed));
        Assert.Equal(seed.ToString(), r.Headers.GetValues("X-Irodori-Seed").Single());

        var bytes = await r.Content.ReadAsByteArrayAsync();
        Assert.True(r.Headers.TransferEncodingChunked);  // the length is unknown until the last piece
        Assert.Equal(0xFFFFFFFFu, BitConverter.ToUInt32(bytes, 40));
        var audio = WavFile.Read(new MemoryStream(bytes));  // the reader takes the data up to the end
        Assert.Equal((int)(FakeEngine.SampleRate * s.Engine.Seconds) * texts.Length, audio.Length);
    }

    [Fact]
    public async Task ClientThatDisconnectsStopsTheRemainingPieces()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        s.Engine.StreamPieces = 2;
        using var hold = new SemaphoreSlim(0);
        s.Engine.HoldAfterFirstPiece = hold;
        using var request = new HttpRequestMessage(HttpMethod.Post, "/v1/audio/speech")
        {
            Content = new StringContent(Speech(LongText).ToJsonString(), System.Text.Encoding.UTF8, "application/json"),
        };

        var r = await s.Client.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, TestContext.Current.CancellationToken);
        var stream = await r.Content.ReadAsStreamAsync(TestContext.Current.CancellationToken);
        // The WAV header and the first streamed half of the first piece: the engine is now held.
        int firstChunk = (int)(FakeEngine.SampleRate * s.Engine.Seconds) / 2 * 2;
        await stream.ReadExactlyAsync(new byte[44 + firstChunk], TestContext.Current.CancellationToken);
        // The client goes away: a read cancelled while it waits closes the connection.
        using (var cut = new CancellationTokenSource())
        {
            var read = stream.ReadAsync(new byte[1 << 16], cut.Token).AsTask();
            cut.Cancel();
            await Assert.ThrowsAnyAsync<Exception>(() => read);
        }
        r.Dispose();
        var aborted = s.Engine.Requests[0].CancellationToken;
        var deadline = DateTime.UtcNow.AddSeconds(10);
        while (!aborted.IsCancellationRequested && DateTime.UtcNow < deadline) await Task.Delay(20, TestContext.Current.CancellationToken);
        Assert.True(aborted.IsCancellationRequested);
        s.Engine.HoldAfterFirstPiece = null;
        hold.Release();

        while (s.Engine.Cancelled == 0 && DateTime.UtcNow < deadline) await Task.Delay(20, TestContext.Current.CancellationToken);
        Assert.Equal(1, s.Engine.Cancelled);
        Assert.Equal(2, s.Engine.Requests.Count);  // the first piece, then the second one gives up at once
    }

    [Fact]
    public async Task EngineThatDoesNotStreamGetsTheConcatenatedWav()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);

        var r = await s.SpeechAsync(Speech(LongText));

        var audio = WavFile.Read(new MemoryStream(await r.Content.ReadAsByteArrayAsync()));
        Assert.Equal((int)(FakeEngine.SampleRate * s.Engine.Seconds) * s.Engine.Requests.Count, audio.Length);
        Assert.Equal(4, s.Engine.Requests.Count);
    }

    [Theory]
    [InlineData("""{"chunking_enabled":false,"chunk_min_chars":10}""")]
    [InlineData("""{"chunk_min_chars":10,"seconds":3}""")]
    [InlineData("""{}""")]  // default 80 non-space characters: the whole text is one piece
    public async Task NotSplitWhenDisabledOrWithFixedSecondsOrShortInput(string irodori)
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        var r = await s.SpeechAsync(Speech(LongText, JsonNode.Parse(irodori)!.AsObject()));
        Assert.Equal(HttpStatusCode.OK, r.StatusCode);
        Assert.Equal(LongText, Assert.Single(s.Engine.Requests).Text);
    }

    [Fact]
    public async Task TopLevelChunkingFlagIsAcceptedLikeIrodoriTtsServer()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        var body = Speech(LongText);
        body["chunking"] = false;
        await s.SpeechAsync(body);
        Assert.Single(s.Engine.Requests);
    }

    [Fact]
    public async Task InvalidChunkOptionIs400()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        var r = await s.SpeechAsync(Speech(LongText, new JsonObject { ["chunk_min_chars"] = 0 }));
        Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode);
        Assert.Empty(s.Engine.Requests);
    }

    private static List<(string Event, JsonObject Data)> ParseEvents(string text) =>
        text.Split("\n\n", StringSplitOptions.RemoveEmptyEntries)
            .Select(block => block.Split('\n'))
            .Select(lines => (lines[0]["event: ".Length..], JsonNode.Parse(lines[1]["data: ".Length..])!.AsObject()))
            .ToList();

    [Fact]
    public async Task SseSendsOneCompleteFilePerPieceThenDone()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        var body = Speech(LongText);
        body["stream_format"] = "sse";

        var r = await s.SpeechAsync(body);

        Assert.Equal("text/event-stream", r.Content.Headers.ContentType?.MediaType);
        var events = ParseEvents(await r.Content.ReadAsStringAsync());
        var pieces = SpeechChunker.Split(LongText, 10);
        Assert.Equal(pieces.Count + 1, events.Count);
        for (int i = 0; i < pieces.Count; i++)
        {
            Assert.Equal("audio_chunk", events[i].Event);
            Assert.Equal(i, (int)events[i].Data["index"]!);
            Assert.Equal(pieces[i], (string?)events[i].Data["text"]);
            Assert.Equal("audio/wav", (string?)events[i].Data["media_type"]);
            var wav = WavFile.Read(new MemoryStream(Convert.FromBase64String((string)events[i].Data["audio_base64"]!)));
            Assert.Equal((int)(FakeEngine.SampleRate * s.Engine.Seconds), wav.Length);
        }
        Assert.Equal("done", events[^1].Event);
        Assert.Equal(pieces.Count, (int)events[^1].Data["chunks"]!);
    }

    [Fact]
    public async Task SseFailureBecomesAnErrorEvent()
    {
        await using var s = await TestServer.StartAsync(prepareVoices: Voices);
        s.Engine.Throw = new ArgumentException("text became empty after normalization.");
        var body = Speech("テスト。");
        body["stream_format"] = "sse";

        var events = ParseEvents(await (await s.SpeechAsync(body)).Content.ReadAsStringAsync());

        var (name, data) = Assert.Single(events);
        Assert.Equal("error", name);
        Assert.Equal("invalid_request_error", (string?)data["error"]!["type"]);
    }
}
